/**
 * Chart geometry for Section 03, extracted from the supplied editable artwork
 * (3/Edgecipline_Chart_Story_4K_Package/assets/02_trading_chart_transparent.svg)
 * so the chart can be drawn as real SVG instead of a flattened bitmap.
 *
 * Generated by scripts/extract-chart-geometry.mjs — edit the artwork and rerun
 * rather than editing this file.
 * All coordinates live in the artwork's own 3840 x 920 viewBox.
 */

export const CHART_VIEWBOX = { width: 3840, height: 920 } as const;

/**
 * The part of the viewBox the artwork actually draws in, measured from the
 * geometry below: candles, price line, echo waves and the r=30 checkpoint
 * rings. Everything that places something over the chart works in these
 * coordinates, so a label and the marker it names cannot drift apart.
 */
export const CHART_FRAME = { x: 1430, y: 175, width: 2420, height: 680 } as const;

/** A point in chart coordinates, as a percentage of CHART_FRAME. */
export function framePosition(x: number, y: number) {
  return {
    left: `${(((x - CHART_FRAME.x) / CHART_FRAME.width) * 100).toFixed(2)}%`,
    top: `${(((y - CHART_FRAME.y) / CHART_FRAME.height) * 100).toFixed(2)}%`,
  };
}

/** Candle bodies start here and repeat every CANDLE_STEP along x. */
export const CANDLE_X0 = 1446;
export const CANDLE_STEP = 23;
export const CANDLE_BODY = { width: 8, height: 24 } as const;
/** The wick extends this far above and below the body. */
export const CANDLE_WICK_OVERSHOOT = 10;

export const CANDLE_UP = "#38bdf8";
export const CANDLE_DOWN = "#39ff88";

/** `<body-top-y><u|d>` per candle, left to right. */
const CANDLES_PACKED =
  "495u 535d 569d 591d 601u 601d 594d 588d 586u 593d 605d 621d 633u 636d 626d 602d 568u 529d 491d 461d 442u 434d 433d 434d 431u 422d 404d 380d 357u 340d 334d 343d 365u 397d 432d 463d 486u 499d 505d 506d 510u 521d 541d 569d 601u 631d 651d 659d 652u 633d 607d 580d 558u 544d 538d 537d 536u 528d 511d 483d 448u 410d 377d 354d 344u 349d 363d 382d 399u 410d 413d 410d 406u 406d 416d 437d 470u 510d 550d 584d 607u 617d 615d 606d 596u 590d 592d 600d 612u 622d 623d 613d 589u 555d 515d 476d 444u 424d 415d 415d 418u 419d 413d 399d 380u";

export type Candle = { x: number; y: number; up: boolean };

export const CANDLES: Candle[] = CANDLES_PACKED.split(" ").map((token, index) => ({
  x: CANDLE_X0 + index * CANDLE_STEP,
  y: Number(token.slice(0, -1)),
  up: token.endsWith("u"),
}));

